skeleton:
variable "app" {
  type = object({
    # name et port obligatoires, les autres avec optional(...)
  })
}

solution:
variable "app" {
  type = object({
    name          = string
    port          = number
    instance_type = optional(string, "t3.micro")
    disk_size     = optional(number, 20)
    public        = optional(bool, false)
  })
}
# Appel minimal : app = { name = "web", port = 8080 }
